with scored as (select id, order_id, method, amount, paid_at, status, last_value(method) ignore nulls over (partition by status order by amount, id rows between unbounded preceding and current row) last_known_method, dense_rank() over (partition by order_id order by amount nulls last) amount_dense_rank, sum(amount) over (partition by order_id order by paid_at, id rows between unbounded preceding and current row) running_amount from payments) select id, method, amount, paid_at, last_known_method, running_amount from scored order by paid_at nulls last
